INSERT INTO food_items (name, slug, summary, description, shops, sources, sort_order, status) VALUES ('Cơm tấm sườn nướng', 'hcm-food-com-tam', 'Cơm tấm ăn cùng sườn nướng, đồ chua và nước mắm pha là một hương vị quen thuộc của Sài Gòn.', 'Cơm tấm được làm từ hạt gạo tấm; thường ăn với sườn nướng, bì, chả hoặc trứng tùy cách gọi món. Điểm hấp dẫn nằm ở sự kết hợp giữa hương thơm của sườn, đồ chua và nước mắm pha. Món này phù hợp cho cả bữa sáng lẫn bữa chính.', 'Cơm tấm Ba Ghiền | 84 Đặng Văn Ngữ, khu Phú Nhuận', 'Cục Du lịch Quốc gia Việt Nam (vietnam.travel)', 10, 'PUBLISHED')
  ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, summary = EXCLUDED.summary, description = EXCLUDED.description, shops = EXCLUDED.shops, sources = EXCLUDED.sources, sort_order = EXCLUDED.sort_order, updated_at = now()
  WHERE food_items.edited_at IS NULL;
INSERT INTO food_items (name, slug, summary, description, shops, sources, sort_order, status) VALUES ('Bánh mì Sài Gòn', 'hcm-food-banh-mi', 'Ổ bánh giòn với nhiều kiểu nhân, rau và nước sốt: lựa chọn nhanh cho một buổi khám phá.', 'Bánh mì là món ăn tiện mang theo khi di chuyển; nhân có thể gồm thịt, chả, pa-tê, rau, đồ chua và ớt. Mỗi quán có phong cách riêng, vì vậy người dùng có thể chọn loại nhân phù hợp khẩu vị. Nếu không ăn cay, hãy nhờ quán bỏ ớt khi gọi.', 'Bánh mì Huỳnh Hoa | 26 Lê Thị Riêng, khu Bến Thành', 'Cục Du lịch Quốc gia Việt Nam (vietnam.travel)', 20, 'PUBLISHED')
  ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, summary = EXCLUDED.summary, description = EXCLUDED.description, shops = EXCLUDED.shops, sources = EXCLUDED.sources, sort_order = EXCLUDED.sort_order, updated_at = now()
  WHERE food_items.edited_at IS NULL;
INSERT INTO food_items (name, slug, summary, description, shops, sources, sort_order, status) VALUES ('Hủ tiếu Nam Vang', 'hcm-food-hu-tieu', 'Tô hủ tiếu với nước dùng thanh, tôm, thịt và rau ăn kèm; cũng có phiên bản khô.', 'Hủ tiếu Nam Vang là một biến thể quen thuộc trong ẩm thực TP.HCM, thường có tôm, thịt và các loại rau tùy quán. Người ăn có thể chọn hủ tiếu nước hoặc hủ tiếu khô; với bản khô, nước dùng thường được phục vụ riêng. Nếu có chế độ ăn đặc biệt, hãy hỏi quán trước khi gọi.', 'Hủ tiếu Ba Hoàng | 56 Võ Văn Tần, khu trung tâm', 'Cục Du lịch Quốc gia Việt Nam (vietnam.travel)', 30, 'PUBLISHED')
  ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, summary = EXCLUDED.summary, description = EXCLUDED.description, shops = EXCLUDED.shops, sources = EXCLUDED.sources, sort_order = EXCLUDED.sort_order, updated_at = now()
  WHERE food_items.edited_at IS NULL;
INSERT INTO food_items (name, slug, summary, description, shops, sources, sort_order, status) VALUES ('Gỏi cuốn', 'hcm-food-goi-cuon', 'Món cuốn mát với bún, rau, thịt và tôm, thường chấm cùng nước sốt đậm vị.', 'Gỏi cuốn kết hợp các nguyên liệu tươi, thường gồm bánh tráng, bún, rau thơm, thịt và tôm. Phần nước chấm thay đổi theo hàng quán. Đây là lựa chọn nhẹ nhàng giữa các điểm tham quan; người dị ứng tôm, đậu phộng hoặc thành phần trong sốt cần hỏi rõ quán.', 'Gỏi cuốn Minh | 84/33 Bùi Viện', 'Cục Du lịch Quốc gia Việt Nam (vietnam.travel)', 40, 'PUBLISHED')
  ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, summary = EXCLUDED.summary, description = EXCLUDED.description, shops = EXCLUDED.shops, sources = EXCLUDED.sources, sort_order = EXCLUDED.sort_order, updated_at = now()
  WHERE food_items.edited_at IS NULL;
INSERT INTO food_items (name, slug, summary, description, shops, sources, sort_order, status) VALUES ('Bánh xèo', 'hcm-food-banh-xeo', 'Chiếc bánh vàng giòn, thường ăn cùng rau sống và nước chấm.', 'Bánh xèo là món bánh mặn có lớp vỏ giòn, nhân có thể gồm tôm, thịt và giá. Một cách thưởng thức phổ biến là cuốn phần bánh với rau rồi chấm nước mắm pha. Khẩu phần và nguyên liệu thay đổi theo quán; nên hỏi trước về hải sản hoặc thành phần gây dị ứng.', 'Bánh xèo 46A | 46A Đinh Công Tráng, khu Tân Định', 'Cục Du lịch Quốc gia Việt Nam (vietnam.travel)', 50, 'PUBLISHED')
  ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, summary = EXCLUDED.summary, description = EXCLUDED.description, shops = EXCLUDED.shops, sources = EXCLUDED.sources, sort_order = EXCLUDED.sort_order, updated_at = now()
  WHERE food_items.edited_at IS NULL;
INSERT INTO food_items (name, slug, summary, description, shops, sources, sort_order, status) VALUES ('Ốc và hải sản kiểu Sài Gòn', 'hcm-food-oc-hai-san', 'Một trải nghiệm ẩm thực buổi tối với nhiều cách chế biến như hấp, nướng và xào.', 'Các quán ốc thường có nhiều lựa chọn hải sản và cách chế biến khác nhau. Khu Vĩnh Khánh được nhắc đến trong các cẩm nang ẩm thực như một khu vực ăn uống sôi động. Hãy hỏi giá theo phần hoặc cân trước khi gọi, và kiểm tra kỹ nguyên liệu nếu có dị ứng hải sản.', 'Ốc Vũ | 37 Vĩnh Khánh, khu Quận 4 trước đây', 'Cục Du lịch Quốc gia Việt Nam (vietnam.travel)', 60, 'PUBLISHED')
  ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, summary = EXCLUDED.summary, description = EXCLUDED.description, shops = EXCLUDED.shops, sources = EXCLUDED.sources, sort_order = EXCLUDED.sort_order, updated_at = now()
  WHERE food_items.edited_at IS NULL;
INSERT INTO historical_stories (slug, title, summary, content, try_this, sources, sort_order, language_code, status, published_at) VALUES ('hcm-story-architecture', 'Giữa những lớp kiến trúc của Sài Gòn', 'Một buổi đi bộ trung tâm có thể đưa bạn qua nhiều dấu ấn kiến trúc khác nhau.', 'Khi đi qua trung tâm TP.HCM, bạn có thể nhận ra thành phố không mang một diện mạo duy nhất. Có những công trình ghi dấu một thời kỳ phát triển đô thị, trong khi đường phố và những không gian công cộng xung quanh tiếp tục thay đổi theo nhịp sống hôm nay.

Bưu điện Trung tâm Sài Gòn dễ nhận ra bởi không gian sảnh rộng và những chi tiết kiến trúc gợi nhắc lịch sử giao thông liên lạc. Nhà hát Thành phố nổi bật ở mặt tiền và vai trò như một điểm hẹn văn hóa. Dinh Độc Lập lại đưa người tham quan vào các không gian trưng bày gắn với lịch sử hiện đại.

Thay vì ghé qua để chụp một tấm ảnh rồi rời đi, hãy chọn một chi tiết để quan sát kỹ hơn: cửa sổ, hành lang, bản đồ hay cách ánh sáng đi vào công trình. Mỗi chi tiết có thể là điểm bắt đầu cho một câu hỏi về đời sống của những người từng sử dụng không gian ấy.', 'Chọn một công trình, đọc bảng giới thiệu tại chỗ, sau đó lưu một ghi chú ngắn về điều khiến bạn chú ý.', 'Cục Du lịch Quốc gia Việt Nam (vietnam.travel); Dinh Độc Lập (dinhdoclap.gov.vn)', 10, 'vi', 'PUBLISHED', now())
  ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, content = EXCLUDED.content, try_this = EXCLUDED.try_this, sources = EXCLUDED.sources, sort_order = EXCLUDED.sort_order, updated_at = now()
  WHERE historical_stories.edited_at IS NULL;
INSERT INTO historical_stories (slug, title, summary, content, try_this, sources, sort_order, language_code, status, published_at) VALUES ('hcm-story-food-culture', 'Câu chuyện của những bữa ăn địa phương', 'Ẩm thực Sài Gòn mang nhiều dấu ấn giao thoa qua những món ăn quen thuộc.', 'Một cách gần gũi để tìm hiểu TP.HCM là bắt đầu bằng một món ăn. Cơm tấm, hủ tiếu và bánh mì xuất hiện ở nhiều khu phố, từ hàng quán nhỏ đến những địa điểm được giới thiệu trong cẩm nang du lịch. Mỗi món lại có nhiều cách chế biến và phục vụ, tùy vùng miền, gia đình và thói quen của người bán.

Cơm tấm gợi nhớ tới bữa ăn quen thuộc với sườn nướng và nước mắm pha. Hủ tiếu thể hiện sự đa dạng trong cách kết hợp sợi, nước dùng và phần ăn kèm. Bánh mì lại thuận tiện cho người muốn dùng một bữa nhanh trước khi tiếp tục hành trình.

Thưởng thức ẩm thực địa phương không nhất thiết phải tìm quán nổi tiếng nhất. Hãy thử quan sát cách mọi người gọi món, hỏi rõ nguyên liệu và dành thời gian cảm nhận hương vị. Đối với du khách quốc tế, việc ghi kèm tên món bằng tiếng Việt sẽ hữu ích khi gọi món hoặc hỏi đường.', 'Lưu một món muốn thử vào danh sách cá nhân, tìm một quán phù hợp với khu vực đang đi và tự ghi lại cảm nhận.', 'Cục Du lịch Quốc gia Việt Nam (vietnam.travel)', 20, 'vi', 'PUBLISHED', now())
  ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, content = EXCLUDED.content, try_this = EXCLUDED.try_this, sources = EXCLUDED.sources, sort_order = EXCLUDED.sort_order, updated_at = now()
  WHERE historical_stories.edited_at IS NULL;
INSERT INTO historical_stories (slug, title, summary, content, try_this, sources, sort_order, language_code, status, published_at) VALUES ('hcm-story-river-city', 'Thành phố nhìn từ bờ sông', 'Bờ sông là nơi dễ cảm nhận sự giao thoa giữa những tuyến phố cũ và đô thị mới.', 'Từ phố Nguyễn Huệ, người đi bộ có thể tiếp tục về hướng Bến Bạch Đằng để nhìn thành phố từ phía sông Sài Gòn. Trên đoạn đường này, không gian đô thị thay đổi dần: từ trục phố rộng, các hàng quán và công trình trung tâm đến cảnh quan ven sông thoáng đãng hơn.

Khu vực bờ sông phù hợp để nghỉ chân, quan sát những phương tiện di chuyển trên mặt nước và cảm nhận nhịp sinh hoạt vào những thời điểm khác nhau trong ngày. Khi trời nắng nóng hoặc có mưa, kế hoạch dạo bộ cũng nên linh hoạt: dừng ở một địa điểm trong nhà, chọn thời điểm mát hơn hoặc rút ngắn hành trình.

Một trải nghiệm khám phá không nhất thiết phải gồm thật nhiều điểm dừng. Đôi khi chỉ cần chọn một góc nhìn, lắng nghe âm thanh thành phố và ghi lại vài dòng cảm nhận là đủ tạo nên kỷ niệm riêng.', 'Chụp một tấm ảnh do bạn sở hữu và ghi lại cảm nhận về thành phố; không bắt buộc chia sẻ công khai vị trí hoặc thời gian đã ghé thăm.', 'Cục Du lịch Quốc gia Việt Nam (vietnam.travel); Wikidata (Bạch Đằng Quay)', 30, 'vi', 'PUBLISHED', now())
  ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, content = EXCLUDED.content, try_this = EXCLUDED.try_this, sources = EXCLUDED.sources, sort_order = EXCLUDED.sort_order, updated_at = now()
